/**
 * @typedef {Object} Inputs
 * @property {*} value
 */

/** @param {Inputs} inputs */
function run(inputs) {
  const rawValue = inputs && inputs["value"];

  // If no input is present, return an empty list to plot an empty graph with axes and legends
  if (!rawValue || (Array.isArray(rawValue) && rawValue.length === 0)) {
    return { "value": [] };
  }

  // If input is already an array, validate/normalize elements
  if (Array.isArray(rawValue)) {
    const formatted = rawValue.map((item, index) => {
      if (item !== null && typeof item === "object" && "value" in item) {
        return {
          label: String(item.label !== undefined ? item.label : index),
          value: Number(item.value) || 0
        };
      } else {
        return {
          label: String(index),
          value: Number(item) || 0
        };
      }
    });
    return { "value": formatted };
  }

  // If input is a single number or string, wrap it
  if (typeof rawValue === "number" || typeof rawValue === "string") {
    return {
      "value": [
        { label: "0", value: Number(rawValue) || 0 }
      ]
    };
  }

  // If input is an object (e.g. key-value pairs), convert to list of points
  if (typeof rawValue === "object") {
    const keys = Object.keys(rawValue);
    const formatted = keys.map(key => ({
      label: String(key),
      value: Number(rawValue[key]) || 0
    }));
    return { "value": formatted };
  }

  // Fallback for any other type
  return { "value": [] };
}

