/**
 * CSV text -> plot-ready points.
 *
 * The chart is drawn by the app, so this only reshapes data: a list of
 * {label, value}. Column names are read from the header rather than
 * hard-coded, so the same node plots any two-column CSV.
 *
 * @typedef {Object} Inputs
 * @property {string} csv
 */

/** @param {Inputs} inputs */
function run(inputs) {
  const lines = String(inputs.csv ?? '').split(/\r?\n/).filter((line) => line.trim());
  if (lines.length < 2) return { points: [] };

  const split = (line) => line.split(/[;,\t]/).map((cell) => cell.trim());
  const header = split(lines[0]);
  const labelColumn = 0;
  const valueColumn = header.length > 1 ? 1 : 0;

  const points = [];
  for (const line of lines.slice(1)) {
    const cells = split(line);
    // German thousands separators: 1.234.567,8 -> 1234567.8
    const raw = String(cells[valueColumn] ?? '').replace(/[ .]/g, '').replace(',', '.');
    const value = Number(raw);
    if (raw === '' || Number.isNaN(value)) continue; // a stray footer line is not a data point
    points.push({ label: String(cells[labelColumn] ?? ''), value: Math.round(value / 100000) / 10 });
  }

  points.sort((a, b) => b.value - a.value);
  return { points };
}
